/*
 * A022329  Exponent of 3 (value of j) in n-th number of the form 2^i*3^j (see
 *          A003586).
 * https://oeis.org/A022329
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = exponent of 3 in the n‑th number of the form 2^i * 3^j
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by a DFS of the 2‑3 lattice sorted by value.
   This implementation uses the standard “ugly numbers” two‑pointer
   technique.  It maintains the list of pairs (i,j) in ascending order,
   and skips duplicates when the two candidates are identical. */

#include <stdlib.h>
#include <math.h>

/* Long‑double constants for log(2) and log(3) – very high precision */
static const long double LOG2_LD = logl(2.0L);
static const long double LOG3_LD = logl(3.0L);

/* Return -1, 0, 1 according as 2^i1*3^j1  <, ==, >  2^i2*3^j2  */
static int cmp_pair(idx_t i1, idx_t j1, idx_t i2, idx_t j2)
{
    if (i1 == i2 && j1 == j2) return 0;

    /* If one pair dominates in both exponents, comparison is obvious */
    if ((i1 >= i2) && (j1 >= j2)) return 1;   /* first larger */
    if ((i1 <= i2) && (j1 <= j2)) return -1;  /* first smaller */

    /* Mixed signs: compare using high‑precision logarithms.  The
       difference between two distinct products is at least ~1e‑5
       for the ranges needed, so a long double is adequate. */
    long double v1 = (long double)i1 * LOG2_LD + (long double)j1 * LOG3_LD;
    long double v2 = (long double)i2 * LOG2_LD + (long double)j2 * LOG3_LD;

    if (v1 < v2) return -1;
    if (v1 > v2) return 1;

    /* Extremely rare floating‑point tie – treat the pairs as equal. */
    return 0;
}

seq_t a(idx_t n)
{
    /* Static storage for the sequence of exponent pairs */
    static idx_t *arr_i = NULL; /* exponent of 2 */
    static idx_t *arr_j = NULL; /* exponent of 3 */
    static size_t  len   = 0;
    static size_t  cap   = 0;

    static idx_t idx2 = 0; /* next position for multiplying by 2 */
    static idx_t idx3 = 0; /* next position for multiplying by 3 */

    /* Initialise on first call */
    if (len == 0) {
        cap   = 64;
        arr_i = (idx_t *)malloc(cap * sizeof(idx_t));
        arr_j = (idx_t *)malloc(cap * sizeof(idx_t));
        arr_i[0] = 0;
        arr_j[0] = 0;
        len     = 1;
    }

    /* Grow buffers if necessary */
    while (len < n) {
        if (len >= cap) {
            cap <<= 1;
            arr_i = (idx_t *)realloc(arr_i, cap * sizeof(idx_t));
            arr_j = (idx_t *)realloc(arr_j, cap * sizeof(idx_t));
        }

        /* Generate two candidate pairs */
        idx_t c2i = arr_i[idx2] + 1;
        idx_t c2j = arr_j[idx2];
        idx_t c3i = arr_i[idx3];
        idx_t c3j = arr_j[idx3] + 1;

        /* If the two candidates are identical, we insert once and
           bump both pointers to avoid duplicates. */
        if (c2i == c3i && c2j == c3j) {
            arr_i[len] = c2i;
            arr_j[len] = c2j;
            idx2++;
            idx3++;
            len++;
            continue;
        }

        /* Pick the smaller of the two candidates */
        if (cmp_pair(c2i, c2j, c3i, c3j) < 0) {
            arr_i[len] = c2i;
            arr_j[len] = c2j;
            idx2++;
        } else {
            arr_i[len] = c3i;
            arr_j[len] = c3j;
            idx3++;
        }
        len++;
    }

    /* Return the exponent of 3 (value of j) for the n-th term */
    return (seq_t)arr_j[n - 1];
}
